mapper.select:
SELECT u.user_id AS userId, u.username AS username, u.mobile AS mobile, u.email AS email, u.nick_name AS nickName, u.avatar_url AS avatarUrl, u.wechat AS wechat, u.password_hash AS passwordHash, m.member_id AS memberId, m.name AS memberName, m.camp_id AS campId, m.role_id AS roleId, r.role_code AS roleCode, r.role_name AS roleName, c.name AS campName, p.poi_id AS poiId, p.poi_name AS poiName FROM pms_user u JOIN pms_member m ON m.user_id = u.user_id AND m.is_deleted = 0 AND m.status = 1 JOIN pms_role r ON r.role_id = m.role_id AND r.is_deleted = 0 AND r.status = 1 LEFT JOIN pms_camp c ON c.camp_id = m.camp_id AND c.is_deleted = 0 LEFT JOIN ( SELECT camp_id, poi_id, poi_name FROM ( SELECT poi.camp_id, poi.poi_id, poi.poi_name, ROW_NUMBER() OVER (PARTITION BY poi.camp_id ORDER BY poi.sort_no ASC, poi.poi_id ASC) AS row_num FROM pms_poi poi WHERE poi.is_deleted = 0 AND poi.status = 1 ) ranked_poi WHERE ranked_poi.row_num = 1 ) p ON p.camp_id = m.camp_id WHERE u.is_deleted = 0 AND u.status = 1 AND (
u.username = #{username}
OR
u.mobile = #{mobile}
OR
u.email = #{email}
) LIMIT 1

SELECT COUNT(*)
FROM pms_user u
WHERE u.is_deleted = 0
  AND (

          u.username = #{username}


          OR


          u.mobile = #{mobile}


          OR


          u.email = #{email}

  )

mapper.update:
UPDATE pms_user
SET
    nick_name = #{nickName},
    email = #{email},
    wechat = #{wechat},
    avatar_url = #{avatarUrl}

        , password_hash = #{passwordHash}

WHERE user_id = #{userId}
  AND is_deleted = 0

UPDATE pms_member
SET
    name = #{name},
    email = #{email}
WHERE user_id = #{userId}
  AND is_deleted = 0

