SELECT cfg.configKey, cfg.configValue, cfg.configScope, cfg.source FROM ( SELECT sc.config_key AS configKey, CAST(sc.config_value AS CHAR) AS configValue, sc.config_scope AS configScope, COALESCE(sc.source, 'system') AS source, sc.system_config_id AS sortOrder FROM system_config sc WHERE sc.camp_id = #{campId}
UNION ALL
SELECT usc.config_key AS configKey, CAST(usc.config_value AS CHAR) AS configValue, 'user' AS configScope, 'user' AS source, 1000000000 + usc.user_system_config_id AS sortOrder FROM user_system_config usc WHERE usc.camp_id = #{campId} AND usc.user_id = #{userId} ) cfg ORDER BY cfg.sortOrder ASC
